import{_ as o,o as i,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — G2 Creator Upload (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g2-creator-upload/plan.md","filePath":"mobile/features/g2-creator-upload/plan.md"}'),l={name:"mobile/features/g2-creator-upload/plan.md"};function c(n,e,r,d,h,s){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="plan-—-g2-creator-upload-mobile" tabindex="-1">Plan — G2 Creator Upload (Mobile) <a class="header-anchor" href="#plan-—-g2-creator-upload-mobile" aria-label="Permalink to &quot;Plan — G2 Creator Upload (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/error cases đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>Backend trước — mobile không chạy được nếu thiếu:</strong><ul><li>Thêm <code>createPresignedUploadUrl(key, contentType, ttlSeconds)</code> vào <code>FileStorageService</code> + <code>S3FileStorageServiceImpl</code> (dùng <code>S3Presigner.presignPutObject</code>, pattern giống <code>createPresignedDownloadUrl</code> đã có sẵn).</li><li>Thêm field <code>taskId</code> (nullable) vào <code>MaterialDocument</code> + <code>MaterialResponse</code> DTO — <strong>xác nhận với backend dev trước khi code vì đây là thay đổi schema Mongo + DTO public</strong> (spec mục 8 câu 4).</li><li>2 endpoint mới: <code>POST /materials/upload-session</code> (xin presigned URL) + <code>POST /materials/upload-session/confirm</code> (tạo Material record).</li><li>Chốt policy max file size trước khi code validate (đề xuất 500MB-1GB).</li></ul></li><li><strong>Mobile dependencies:</strong><ul><li><code>expo install expo-camera expo-image-picker</code> (chưa có trong <code>package.json</code>).</li><li>Xác nhận <code>expo-file-system</code> hỗ trợ <code>createUploadTask</code> với progress callback.</li></ul></li><li><strong>Task List/Detail (phụ thuộc G5 nếu đã có, dùng API Task tạm nếu chưa):</strong><ul><li>Task List lọc theo <code>assigneeId=currentUser</code>, status chưa FINISHED/CANCELLED.</li><li>Task Detail thêm 2 nút &quot;Quay video&quot; / &quot;Chọn từ thư viện&quot;.</li></ul></li><li><strong>Upload flow:</strong><ul><li>Màn Upload → gọi <code>upload-session</code> lấy <code>uploadUrl</code>+<code>s3Key</code> → <code>FileSystem.createUploadTask</code> PUT với progress bar → confirm.</li><li>Resilience: retry 3 lần network error, giữ file local tới khi confirm xong, xử lý 403 signature-expired (gọi lại <code>upload-session</code> lấy key mới).</li></ul></li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>1 presigned PUT duy nhất cho toàn file</strong>, không làm S3 Multipart Upload thật (effort quá lớn so với capstone) — retry khi mất mạng là restart từ đầu, không resume byte-level.</li><li><strong>Upload chỉ chạy foreground</strong> (giới hạn Expo managed đã chốt ở <code>mobile-app-plan.md</code>) — dừng khi app bị kill/minimize, resume khi mở lại.</li><li><strong>Video không đi qua nhánh <code>uploadMaterial</code>/<code>uploadImage</code> hiện có</strong> (convert WebP, upload qua server) — nhánh đó chỉ hợp lý cho ảnh, không dùng cho video vài trăm MB.</li><li><strong>Video compression: MVP không làm</strong> — giữ nguyên file gốc từ camera/gallery. Nếu dung lượng gây vấn đề thực tế, giảm resolution record 720p trong <code>expo-camera</code> config thay vì compress sau khi quay.</li></ul><h2 id="viec-backend-can-xac-nhan-truoc-khi-mobile-code-chua-lam-xem-spec-muc-8" tabindex="-1">Việc backend cần xác nhận trước khi mobile code (chưa làm, xem spec mục 8) <a class="header-anchor" href="#viec-backend-can-xac-nhan-truoc-khi-mobile-code-chua-lam-xem-spec-muc-8" aria-label="Permalink to &quot;Việc backend cần xác nhận trước khi mobile code (chưa làm, xem spec mục 8)&quot;">​</a></h2><ul><li>Giới hạn dung lượng file chưa chốt số cụ thể — cần backend validate ở <code>upload-session</code> trước khi cấp presigned URL.</li><li>Field <code>taskId</code> mới trên <code>MaterialDocument</code> — xác nhận không ảnh hưởng Material cũ tạo từ web (field optional/nullable).</li><li>HEAD-object verify trước khi lưu Material ở bước confirm — MVP có thể bỏ qua, đổi lại chấp nhận rủi ro nhỏ record &quot;ma&quot; nếu client confirm sai.</li></ul><h2 id="rui-ro-con-mo" tabindex="-1">Rủi ro còn mở <a class="header-anchor" href="#rui-ro-con-mo" aria-label="Permalink to &quot;Rủi ro còn mở&quot;">​</a></h2><ul><li>Nếu mạng rớt ở 90% của file vài trăm MB, phải PUT lại từ đầu — hạn chế đã biết của approach &quot;presigned PUT đơn&quot;, không phải bug.</li><li>Nếu client mất kết nối sau khi PUT xong nhưng trước khi confirm: mobile phải giữ <code>s3Key</code>+<code>taskId</code> ở local storage để cho phép gọi lại confirm trực tiếp khi mở lại app, không PUT lại.</li></ul>',10)])])}const m=o(l,[["render",c]]);export{p as __pageData,m as default};
